import React from "react";
import {
  AbsoluteFill,
  interpolate,
  interpolateColors,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load font at module level
const { fontFamily: interFamily } = loadInter();

// --- Schema Definition ---


export type CoverageDashboardProps = Record<string, any>;

// --- Helper Components & Icons ---
const LightningIcon = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M13 2L3 14H12L11 22L21 10H12L13 2Z" fill="#FACC15" />
  </svg>
);

const PdfIcon = ({ opacity, scale, y, x }: { opacity: number; scale: number; y: number; x: number }) => (
  <div
    style={{
      position: "absolute",
      left: x,
      top: y,
      transform: `translate(-50%, -50%) scale(${scale})`,
      opacity,
      width: 120,
      height: 160,
      backgroundColor: "#EF4444",
      borderRadius: 12,
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
      zIndex: 100,
      color: "white",
      fontWeight: "bold",
      fontSize: 32,
      fontFamily: interFamily,
      border: "4px solid white"
    }}
  >
    <div style={{ backgroundColor: "white", color: "#EF4444", padding: "4px 12px", borderRadius: 4, fontSize: 24 }}>
      PDF
    </div>
  </div>
);

// --- Main Component ---
const CoverageDashboard: React.FC<CoverageDashboardProps> = ({
  backgroundColor = "#e0fbed",
  transparentBackground = false,
  durationInSeconds = 12,
  primaryGreen = "#1d8c60",
  bannerBg = "#0a0a0a",
  bannerText = "#00e676",
  surfaceColor = "#ffffff",
  textColor = "#111827",
  uploadTitle = "Choose Script",
  uploadSubtitle = "Only PDF format is supported",
  startReports = 0,
  totalReports = 26,
  newScriptTitle = "eternal-sunshine.pdf",
  newScriptRank = 99,
  newScriptRating = 9.5,
  existingScripts = [
    { title: "Script.pdf", status: "Ready", rank: 10, rating: 3.1 },
    { title: "Script_v2.pdf", status: "Ready", rank: 12, rating: 4.2 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timings ---
  // 0-30: Idle
  // 30-70: PDF Drag & Drop
  // 70-85: Button Pulse
  // 85-240: Loading Gauge fills, timer ticks, counter ticks
  // 240-260: Gauge completes, flashes
  // 260-290: New row slides in (Status: Pending)
  // 310-330: Status snaps to Ready, Numbers count up

  // 1. Drag & Drop Animation
  const isDragging = frame >= 30 && frame <= 70;
  const pdfStartY = height * 0.8;
  const pdfEndY = height * 0.3; // Approx center of upload box
  const pdfX = width * 0.5;
  
  const pdfY = interpolate(frame, [30, 65], [pdfStartY, pdfEndY], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 1, 0.5, 1) 
  });
  
  const pdfScale = interpolate(frame, [30, 40, 65, 70], [0, 1, 1, 0.5], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  const pdfOpacity = interpolate(frame, [30, 40, 65, 75], [0, 1, 1, 0], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // 2. Button Pulse (triggers when PDF drops)
  const buttonScale = interpolate(frame, [70, 77, 85], [1, 1.05, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const buttonBgColor = interpolateColors(frame, [70, 77, 85], ["#000000", primaryGreen, "#000000"]);

  // 3. Loading Gauge Animation
  const loadStart = 85;
  const loadEnd = 240;
  const loadingProgress = interpolate(frame, [loadStart, loadEnd], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease)
  });

  // Gauge SVG calculations (180 deg arc)
  const gaugeRadius = 160;
  const gaugeCircumference = Math.PI * gaugeRadius;
  const strokeDashoffset = interpolate(loadingProgress, [0, 1], [gaugeCircumference, 0]);
  
  const gaugeFlashColor = interpolateColors(
    frame, 
    [loadEnd, loadEnd + 10, loadEnd + 20], 
    ["#d1d5db", primaryGreen, primaryGreen] // Gray to Green (stays green)
  );

  // 4. Timer & Counter
  // 15 minutes = 900 seconds
  const timerSecondsLeft = interpolate(frame, [loadStart, loadEnd], [900, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const timerMins = Math.floor(timerSecondsLeft / 60).toString().padStart(2, '0');
  const timerSecs = Math.floor(timerSecondsLeft % 60).toString().padStart(2, '0');
  const timerDisplay = loadingProgress > 0 && loadingProgress < 1 ? `${timerMins}:${timerSecs}` : "00:00";
  const timerOpacity = interpolate(frame, [loadStart - 5, loadStart + 10, loadEnd, loadEnd + 15], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const currentReportsCount = Math.floor(interpolate(loadingProgress, [0, 1], [startReports, startReports + 1]));

  // 5. New Row Animation
  const rowAnimStart = 260;
  const rowEnterProgress = spring({
    frame: frame - rowAnimStart,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  
  const rowHeight = interpolate(rowEnterProgress, [0, 1], [0, 100], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const rowOpacity = interpolate(rowEnterProgress, [0, 1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  // 6. Status & Numbers Population
  const populateStart = 310;
  const isReady = frame >= populateStart;
  
  const statusBg = isReady ? primaryGreen : "#9ca3af";
  const statusText = isReady ? "Ready" : "Pending";
  
  const displayRank = Math.floor(interpolate(frame, [populateStart, populateStart + 15], [0, newScriptRank], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  }));
  
  const displayRating = interpolate(frame, [populateStart + 5, populateStart + 20], [0, newScriptRating], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  }).toFixed(1);


  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, color: textColor }}>
      
      {/* Top Nav (Mock) */}
      <div style={{ height: 80, backgroundColor: surfaceColor, display: "flex", alignItems: "center", padding: "0 40px", justifyContent: "space-between", borderBottom: "1px solid #e5e7eb" }}>
        <div style={{ display: "flex", gap: 40, fontWeight: 500, fontSize: 20 }}>
          <span>Home</span>
          <span style={{ borderBottom: `4px solid ${primaryGreen}`, paddingBottom: 28, marginTop: 28 }}>Dashboard</span>
          <span style={{ color: "#6b7280" }}>Insider Series</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
          <span style={{ fontSize: 18 }}>Welcome! 👋</span>
          <div style={{ border: "1px solid #e5e7eb", padding: "8px 16px", borderRadius: 8 }}>My Account</div>
        </div>
      </div>

      {/* Banner */}
      <div style={{ backgroundColor: bannerBg, color: bannerText, padding: "24px 40px", display: "flex", alignItems: "center", justifyContent: "center", gap: 16, fontSize: 24, fontWeight: 600, textAlign: "center", lineHeight: 1.4 }}>
        <LightningIcon />
        <span>Submit your scripts to The Greenlight List! Grand Prize: $100,000 + distribution.</span>
      </div>

      {/* Main Content Area */}
      <div style={{ flex: 1, display: "flex", flexDirection: "column", padding: "40px 60px", gap: 40, overflow: "hidden" }}>
        
        {/* Upload Box */}
        <div style={{ 
          backgroundColor: surfaceColor, 
          borderRadius: 16, 
          padding: "60px 40px", 
          display: "flex", 
          flexDirection: "column", 
          alignItems: "center", 
          justifyContent: "center",
          boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03)",
          position: "relative"
        }}>
          <div style={{
            backgroundColor: buttonBgColor,
            color: "white",
            padding: "16px 40px",
            borderRadius: 8,
            fontSize: 24,
            fontWeight: 600,
            transform: `scale(${buttonScale})`,
            transition: "none",
            marginBottom: 20
          }}>
            {uploadTitle}
          </div>
          <div style={{ fontSize: 20, color: "#6b7280" }}>{uploadSubtitle}</div>
        </div>

        {/* Gauge Area */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", position: "relative", height: 220 }}>
          {/* SVG Semicircle */}
          <svg width={gaugeRadius * 2 + 40} height={gaugeRadius + 20} viewBox={`0 0 ${gaugeRadius * 2 + 40} ${gaugeRadius + 20}`}>
            {/* Track Background */}
            <path
              d={`M 20 ${gaugeRadius + 10} A ${gaugeRadius} ${gaugeRadius} 0 0 1 ${gaugeRadius * 2 + 20} ${gaugeRadius + 10}`}
              fill="none"
              stroke="#e5e7eb"
              strokeWidth="24"
              strokeLinecap="round"
            />
            {/* Animated Fill */}
            <path
              d={`M 20 ${gaugeRadius + 10} A ${gaugeRadius} ${gaugeRadius} 0 0 1 ${gaugeRadius * 2 + 20} ${gaugeRadius + 10}`}
              fill="none"
              stroke={loadingProgress === 1 ? gaugeFlashColor : "#d1d5db"} // Active fill is gray until complete
              strokeWidth="24"
              strokeLinecap="round"
              strokeDasharray={gaugeCircumference}
              strokeDashoffset={strokeDashoffset}
              style={{ transition: "none" }}
            />
          </svg>
          
          {/* Inner Gauge Text */}
          <div style={{ position: "absolute", bottom: 20, display: "flex", flexDirection: "column", alignItems: "center" }}>
            <div style={{ fontSize: 42, fontWeight: 700 }}>{currentReportsCount}/{totalReports}</div>
            <div style={{ fontSize: 18, color: "#6b7280" }}>Coverage Reports Used</div>
          </div>
          
          {/* Timer */}
          <div style={{ position: "absolute", top: 40, right: width * 0.15, fontSize: 24, fontWeight: 600, color: primaryGreen, opacity: timerOpacity, display: "flex", alignItems: "center", gap: 8 }}>
            ⏱ {timerDisplay}
          </div>
        </div>

        {/* Scripts Table (List View for Vertical layout) */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16, flex: 1 }}>
          {/* Header */}
          <div style={{ display: "flex", padding: "0 24px", color: "#4b5563", fontWeight: 600, fontSize: 18, borderBottom: "2px solid #d1d5db", paddingBottom: 12 }}>
            <div style={{ flex: 2 }}>Script File</div>
            <div style={{ flex: 1, textAlign: "center" }}>Status</div>
            <div style={{ flex: 1, textAlign: "center" }}>Rank</div>
            <div style={{ flex: 1, textAlign: "center" }}>Rating</div>
          </div>

          {/* Existing Rows */}
          {existingScripts.map((script, i) => (
            <div key={i} style={{ display: "flex", padding: "20px 24px", backgroundColor: surfaceColor, borderRadius: 12, alignItems: "center", boxShadow: "0 1px 3px rgba(0,0,0,0.05)" }}>
              <div style={{ flex: 2, fontWeight: 500, fontSize: 20 }}>{script.title}</div>
              <div style={{ flex: 1, display: "flex", justifyContent: "center" }}>
                <span style={{ backgroundColor: primaryGreen, color: "white", padding: "6px 16px", borderRadius: 4, fontSize: 16, fontWeight: 600 }}>{script.status}</span>
              </div>
              <div style={{ flex: 1, textAlign: "center", fontWeight: 700, fontSize: 20 }}>{script.rank}</div>
              <div style={{ flex: 1, textAlign: "center", fontWeight: 700, fontSize: 20 }}>{script.rating.toFixed(1)}</div>
            </div>
          ))}

          {/* New Animated Row */}
          <div style={{ 
            display: "flex", 
            padding: "0 24px", 
            backgroundColor: surfaceColor, 
            borderRadius: 12, 
            alignItems: "center", 
            boxShadow: "0 4px 6px rgba(0,0,0,0.05)",
            height: rowHeight,
            opacity: rowOpacity,
            overflow: "hidden",
            border: isReady ? `2px solid ${primaryGreen}33` : "none"
          }}>
             {rowOpacity > 0.5 && (
               <>
                <div style={{ flex: 2, fontWeight: 500, fontSize: 20, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                  {newScriptTitle}
                </div>
                <div style={{ flex: 1, display: "flex", justifyContent: "center" }}>
                  <span style={{ 
                    backgroundColor: statusBg, 
                    color: "white", 
                    padding: "6px 16px", 
                    borderRadius: 4, 
                    fontSize: 16, 
                    fontWeight: 600,
                    transition: "none" 
                  }}>
                    {statusText}
                  </span>
                </div>
                <div style={{ flex: 1, textAlign: "center", fontWeight: 700, fontSize: 20 }}>
                  {displayRank > 0 ? displayRank : "-"}
                </div>
                <div style={{ flex: 1, textAlign: "center", fontWeight: 700, fontSize: 20 }}>
                  {displayRating !== "0.0" ? displayRating : "-"}
                </div>
               </>
             )}
          </div>
        </div>
      </div>

      {/* Floating Animated PDF */}
      {frame >= 30 && frame <= 75 && (
        <PdfIcon x={pdfX} y={pdfY} scale={pdfScale} opacity={pdfOpacity} />
      )}

    </AbsoluteFill>
  );
};

export default CoverageDashboard;